(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20+Math.cos(y*0.012-t*0.15)*15;
  const w1y = Math.cos(y*0.015-t*0.18)*20+Math.sin(x*0.013+t*0.22)*15;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025+t*0.3)*8+Math.cos(my*0.02-t*0.25)*6;
  const w2y = Math.cos(my*0.025-t*0.28)*8+Math.sin(mx*0.022+t*0.32)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65)*50,0.11,1.8],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+1)*70,0.05,2.8]
  ];
  let aS=0,iS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
  }
  const act=aS/8,inh=iS/8;
  const bg1=Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1);
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.3+Math.sin((sx-sy)*0.1-t*2)*0.3;
  const bg3=Math.sin(sx*0.08+sy*0.06-t*1.5)*0.2+Math.cos(sx*0.05-sy*0.09+t*1.8)*0.2;
  const bg=(bg1+bg2+bg3)/2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2=Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3=Math.sin(dist*0.07-ang*2+t*0.8)*0.5;
  const spiral=(sp1+sp2+sp3)*0.3;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const crossA=Math.sin(act*2.5+inh*1.5-t*0.5)*0.2;
  const crossI=Math.cos(inh*2.0-act*1.8+t*0.3)*0.15;
  const pulse=Math.sin(dist*0.03-t*1.8)*Math.exp(-dist*0.005)*0.25;
  const raw=act-inh*0.7+bg*0.3+spiral+crossA-crossI+pulse;
  const reaction=Math.tanh(raw*2.2);
  const edgeGlow=Math.abs(reaction)>0.6?Math.pow(Math.abs(reaction),0.5)*0.3:0;
  const blend=reaction*0.65+cell*0.2+edgeGlow*0.15;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[10,45,85],[15,95,120],[25,155,135],
    [140,190,100],[220,185,60],[215,130,65],
    [185,75,75],[120,35,65],[50,15,55],[5,12,52]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge)|0
  ];
}
